INSERT OR IGNORE INTO benchmark_definitions (id, name, description, type, config) VALUES (
  'tool-calling-v1',
  'Tool Calling v1',
  'Tests correct tool selection and argument accuracy across 10 prompts.',
  'tool_calling',
  '{"tools":[{"name":"get_weather","description":"Get current weather for a location","parameters":{"type":"object","properties":{"location":{"type":"string"},"unit":{"type":"string","enum":["celsius","fahrenheit"]}},"required":["location"]}},{"name":"search_web","description":"Search the internet for information","parameters":{"type":"object","properties":{"query":{"type":"string"}},"required":["query"]}},{"name":"send_email","description":"Send an email to a recipient","parameters":{"type":"object","properties":{"to":{"type":"string"},"subject":{"type":"string"},"body":{"type":"string"}},"required":["to","subject","body"]}}],"test_cases":[{"prompt":"What''s the weather in Austin, TX?","expected_tool":"get_weather","expected_args":{"location":"Austin, TX"}},{"prompt":"Find recent news about the EU AI Act","expected_tool":"search_web","expected_args":{"query":"EU AI Act"}},{"prompt":"Email jordan@example.com with subject ''hello'' and body ''testing''","expected_tool":"send_email","expected_args":{"to":"jordan@example.com"}},{"prompt":"Is it going to rain in Seattle tomorrow?","expected_tool":"get_weather","expected_args":{"location":"Seattle"}},{"prompt":"Search for the best Hono.js tutorials","expected_tool":"search_web","expected_args":{"query":"Hono.js tutorials"}},{"prompt":"Send a meeting reminder to team@acme.com","expected_tool":"send_email","expected_args":{"to":"team@acme.com"}},{"prompt":"What''s the temperature in Tokyo right now?","expected_tool":"get_weather","expected_args":{"location":"Tokyo"}},{"prompt":"Look up Cloudflare Workers pricing","expected_tool":"search_web","expected_args":{"query":"Cloudflare Workers pricing"}},{"prompt":"Notify ops@company.com that the deploy is done","expected_tool":"send_email","expected_args":{"to":"ops@company.com"}},{"prompt":"How cold is it in Reykjavik?","expected_tool":"get_weather","expected_args":{"location":"Reykjavik"}}]}'
);
